with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('tage ved lære', 'phrase', '0ed08560-cf1c-5ad5-86eb-10443a0e98f1', 1, 'verb', null, 'вчитися на досвіді', 'Han tog ved lære af sine fejl.', 'Він навчився на своїх помилках.'), ('rejse sig op', 'phrase', '42d159f1-2083-5317-97e4-3a972236f90c', 1, 'verb', null, 'вставати (із сидячого або лежачого положення)', 'Hun rejser sig op fra stolen og går hen til vinduet.', 'Вона встає зі стільця і підходить до вікна.'), ('være ude at rejse', 'phrase', 'ae654ce7-46ad-5363-841d-e575c203e667', 1, 'verb', null, 'подорожувати (бути в поїздці)', 'Min søster er ude at rejse i denne uge.', 'Моя сестра цього тижня подорожує.'), ('lukke ned', 'phrase', '0333cfd9-032e-5060-a7ef-744996e6ea84', 1, 'verb', null, 'закривати (бізнес, систему)', 'Virksomheden lukkede ned efter mange år med underskud.', 'Компанія закрилася після багатьох років збитків.'), ('lukke op', 'phrase', 'e6a7d336-8bcd-5012-aa2f-a4753c6cd6d0', 1, 'verb', null, 'відчиняти (двері, вікно тощо)', 'Hun lukker op for gæsterne, når de ringer på.', 'Вона відчиняє двері гостям, коли вони дзвонять у двері.'), ('lukke øjnene for', 'phrase', '2159d728-7068-5bb2-a555-f90192658880', 1, 'verb', null, 'заплющувати очі на (ігнорувати)', 'Mange lukker øjnene for problemerne i samfundet.', 'Багато людей закривають очі на проблеми в суспільстві.'), ('hen imod', 'phrase', 'a74051c8-82e6-5a6b-ba9b-95629703a9b2', 1, 'preposition', null, 'до (про час)', 'Det bliver koldt hen imod aften.', 'Надвечір стане холодно.'), ('sætte sig hen', 'phrase', '43497df0-216a-5237-b560-85c4119ffd82', 1, 'verb', null, 'сісти (перемістившись)', 'Hun sætter sig hen ved vinduet hver morgen.', 'Вона сідає біля вікна щоранку.'), ('sælge sig selv', 'phrase', '2cf4c858-0f21-52b7-b4c5-729d01f33495', 1, 'verb', null, 'продавати себе (вигідно подавати)', 'Til jobsamtalen skal du sælge dig selv på en god måde.', 'На співбесіді потрібно добре себе представити.'), ('arbejde sort', 'phrase', 'd2c6214d-145d-57ef-b93b-0747792eff54', 1, 'verb', null, 'працювати нелегально (без сплати податків)', 'Mange håndværkere arbejder sort om sommeren.', 'Багато ремісників влітку працюють нелегально.'), ('gå i sort', 'phrase', 'cfe6b936-e1b0-5e81-aa58-d6203ca87271', 1, 'verb', null, 'зависнути (про комп’ютер, техніку)', 'Min computer gik i sort midt i mødet.', 'Мій комп''ютер завис посеред зустрічі.'), ('tage på tur', 'phrase', 'db5837c2-eadd-5604-ba23-f8491fab6f33', 1, 'verb', null, 'вирушати в подорож', 'Vi tager på tur til stranden i morgen.', 'Завтра вирушаємо в подорож на пляж.'), ('rødt kort', 'phrase', '6ec4a9d7-a356-580d-97e4-f32c3f780f10', 1, 'phrase', null, 'червона картка (у спорті)', 'Dommeren viste ham et rødt kort.', 'Арбітр показав йому червону картку.'), ('se rødt', 'phrase', 'e38a6e2f-7dc3-5704-8ca6-f56c4cfd4e07', 1, 'verb', null, 'розлютитися', 'Jeg ser rødt, når nogen lyver for mig.', 'Я розлючуюся, коли хтось мені бреше.'), ('være skyld i', 'phrase', '9160df79-f917-5f2e-840c-1eab561bd78e', 1, 'verb', null, 'бути причиною (чогось поганого)', 'Den kraftige regn var skyld i oversvømmelsen.', 'Сильний дощ був причиною повені.'), ('passe ind', 'phrase', 'a9aa180f-eafb-5cfb-86e2-025a898c4ca5', 1, 'verb', null, 'вписуватися (у колектив, обстановку)', 'Han passer ind i den nye klasse.', 'Він вписується в новий клас.'), ('passe sig', 'phrase', '2e0a7e93-bad5-5abb-9b05-1b1f0c35e5d8', 1, 'verb', null, 'бути доречним, личити', 'Det passer sig ikke at tale højt i kirken.', 'Недоречно говорити голосно в церкві.'), ('hænge fast', 'phrase', 'c6d4806d-129c-5309-942a-704a6f5a7092', 1, 'verb', null, 'застрягати (зачепившись)', 'Min jakke hang fast i døren.', 'Моя куртка застрягла в дверях.'), ('hænge fast', 'phrase', 'fc976d02-b60c-5f23-926f-128ee0c286cb', 2, 'verb', null, 'зависати (про комп''ютер)', 'Computeren hænger fast igen.', 'Комп''ютер знову завис.'), ('hænge sig i', 'phrase', '49270748-ce11-5e07-b56f-e80b2fa01413', 1, 'verb', null, 'зациклюватися (на дрібницях)', 'Du hænger dig i små fejl hele tiden.', 'Ти постійно зациклюєшся на дрібних помилках.'), ('hænge ved', 'phrase', '8e08a5e1-b8ce-5fef-b227-9496972daebb', 1, 'verb', null, 'прилипати (про запах, бруд)', 'Røglugten hang ved mit tøj efter festen.', 'Запах диму прилип до мого одягу після вечірки.'), ('stemme om', 'phrase', '65960fb4-8b7b-5c95-b96c-fec7cc8c7d14', 1, 'verb', null, 'голосувати (з якогось питання)', 'Vi stemmer om forslaget i morgen.', 'Ми проголосуємо щодо пропозиції завтра.'), ('blive rød i hovedet', 'phrase', '80e73576-9209-595b-b70a-fceb41c4548f', 1, 'verb', null, 'червоніти (від збентеження)', 'Hun bliver rød i hovedet, når hun får komplimenter.', 'Вона червоніє, коли отримує компліменти.'), ('hænge med hovedet', 'phrase', 'dbb41d9b-cf12-5d41-b398-cb6c71d92883', 1, 'verb', null, 'журитися, бути пригніченим', 'Han hang med hovedet hele dagen efter nyheden.', 'Він журився весь день після новини.'), ('regne efter', 'phrase', 'bd3846eb-dee1-5bb5-a3da-2a7dd8301c2f', 1, 'verb', null, 'перераховувати, перевіряти (розрахунок)', 'Jeg regner efter for at være sikker.', 'Я роблю підрахунки, щоб переконатися.'), ('mærke på', 'phrase', '9c645e45-3173-5a88-a231-a2c01ffaf7e7', 1, 'verb', null, 'відчувати (на дотик, на смак тощо)', 'Jeg kan mærke på glasset at det er varmt.', 'Я відчуваю по склянці, що вона гаряча.'), ('komme til magten', 'phrase', '687b8263-c0ed-51c1-8b6a-a7cab5bb1f08', 1, 'verb', null, 'приходити до влади', 'Partiet kom til magten efter et tæt valg.', 'Партія прийшла до влади після напружених виборів.'), ('sige stop', 'phrase', 'c99b5f53-6d69-5245-b2db-17bc412f9223', 1, 'verb', null, 'зупинятися, припиняти (щось)', 'Han sagde stop efter tre års studier.', 'Він залишив навчання після трьох років.'), ('handle derefter', 'phrase', 'ba935f54-5854-5a25-a4af-b4a16d1f1e99', 1, 'verb', null, 'діяти відповідно', 'Jeg forstår beskeden og handler derefter.', 'Я розумію послання і дію відповідно.'), ('bære på', 'phrase', '7cbe18d6-78f6-5a8d-94ce-a085ee4c4df2', 1, 'verb', null, 'нести (в руках)', 'Hun bærer på en tung kasse.', 'Вона несе важку коробку.'), ('bære på', 'phrase', '48dce0c5-20b9-589b-8f67-c23c990f7c5c', 2, 'verb', null, 'відчувати (почуття)', 'Han bærer på en stor sorg.', 'Він несе в собі велику печаль.'), ('holde pause', 'phrase', '17d3e9cf-88c7-5654-8474-8e54c344f311', 1, 'verb', null, 'робити перерву', 'Vi holder pause klokken tolv.', 'Робимо перерву о дванадцятій.'), ('slå fejl', 'phrase', '6fd2b113-53a3-5320-8e0d-2cf0f4d1680d', 1, 'verb', null, 'не вдаватися, провалюватися', 'Planen slog fejl, og vi måtte starte forfra.', 'План провалився, і нам довелося починати все спочатку.'), ('få besøg', 'phrase', '3bee2ab8-ed74-5688-83eb-0f3d00c0c904', 1, 'verb', null, 'приймати гостей', 'Vi får besøg af mine forældre i weekenden.', 'Цього вікенду до нас приїдуть мої батьки.'), ('være på besøg hos', 'phrase', '8ccd6f46-4458-5fab-a385-43deac6845f4', 1, 'verb', null, 'бути в гостях у (когось)', 'Jeg er på besøg hos min ven i dag.', 'Сьогодні я в гостях у друга.'), ('tjene på', 'phrase', '50da5ab9-9bf5-578e-aff8-ae6768f4957c', 1, 'verb', null, 'заробляти на (чомусь)', 'De tjener på at sælge gamle møbler.', 'Вони заробляють гроші, продаючи старі меблі.'), ('det er slut', 'phrase', '95d2a870-ff66-5dfb-b372-a00615bad506', 1, 'phrase', null, 'усе скінчено', 'Det er slut med gratis kaffe på kontoret.', 'Більше ніякої безкоштовної кави в офісі.'), ('give koncert', 'phrase', 'fe587f42-56bb-574c-ac4d-391eeedad903', 1, 'verb', null, 'давати концерт', 'Bandet giver koncert i parken på lørdag.', 'У суботу гурт дасть концерт у парку.'), ('tage magten', 'phrase', 'e31e5516-00c3-5eec-8560-ce25f63d3151', 1, 'verb', null, 'захопити владу', 'Oprørerne tog magten i landet efter krigen.', 'Після війни повстанці захопили владу в країні.'), ('gå ud at spise', 'phrase', 'cb143ec2-fc72-5c9f-9868-1fc5ed53093e', 1, 'verb', null, 'ходити в ресторан (їсти поза домом)', 'Vi gik ud at spise i fredags.', 'У п''ятницю ми ходили в ресторан.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'uk'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'uk', text, pos, gender, example, example_translation, 'pipeline-phrases-0013' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
